import { formatMoney, formatNumber } from '../../../../../../../helpers/utility'
import { HOURGLASS_GOLD } from '../../../../../../../images'
import { RENEWAL_ALLOCATION } from '../../container/constants'
import { StyleContainer } from './index.styles'

function PolicySummaryCard({ oldPolicyData, comparisonData }) {
  const isUwReview = oldPolicyData?.renewal_allocation === RENEWAL_ALLOCATION.UW_REVIEW
  return (
    <StyleContainer data-testid="renewal-one-tap-policy-summary">
      <div className="content">
        <img
          className="logo"
          src={comparisonData?.package?.new_policy?.provider?.logo_url}
          alt=""
        />
        <div className="provider">{comparisonData?.package?.new_policy?.provider.name}</div>
        <div className="product">{comparisonData?.package?.new_policy?.product?.name}</div>

        <div className="divider">
          <div className="triple">
            <div>
              <div className="label">Premi Dasar</div>
              <div className="value">
                {isUwReview ? (
                  <img src={HOURGLASS_GOLD} alt="pending" />
                ) : (
                  formatMoney(comparisonData?.premium?.new_policy?.total_premium?.premium, 0)
                )}
              </div>
            </div>
            <div>
              <div className="label">Total Komisi</div>
              <div className="value">
                {isUwReview ? (
                  <img src={HOURGLASS_GOLD} alt="pending" />
                ) : (
                  formatMoney(comparisonData?.commission?.new_policy?.commission_amount, 0)
                )}
              </div>
            </div>
            <div>
              <div className="label">Total Poin</div>
              <div className="value">
                {isUwReview ? (
                  <img src={HOURGLASS_GOLD} alt="pending" />
                ) : (
                  formatNumber(comparisonData?.commission?.new_policy?.points_amount || 0, {
                    suffix: ' P',
                  })
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </StyleContainer>
  )
}

export default PolicySummaryCard
