import { getRemainingDatetime } from '../../../../../../../helpers/formatDate'
import { getRenewalExpiryColor, RENEWAL_EXPIRY } from './helpers'
import { StyleContainer } from './index.styles'

function HeaderCountdown({ oldPolicyData }) {
  const expiry = getRenewalExpiryColor(oldPolicyData?.coverage_end_date)
  return (
    <StyleContainer expiry={expiry} data-testid="renewal-one-tap-header-countdown">
      <div className="text">
        {[RENEWAL_EXPIRY.URGENT, RENEWAL_EXPIRY.WARNING].includes(expiry) && (
          <div>Lakukan perpanjangan polis, karena polis akan berakhir dalam:</div>
        )}
        {[RENEWAL_EXPIRY.EXPIRED].includes(expiry) && (
          <div>
            Lakukan perpanjangan polis, sebelum jatuh tempo polis lebih dari +14 hari lewat.
          </div>
        )}
      </div>
      <div>
        <div className="status-pill">{getRemainingDatetime(oldPolicyData?.coverage_end_date)}</div>
      </div>
    </StyleContainer>
  )
}

export default HeaderCountdown
