import moment from 'moment'
import { CustomText } from '../../../../../../../components'
import UploadFileV3 from '../../../../../../../components/DynamicForm/components/UploadFileV3'
import { Row } from '../../../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { formatMoney } from '../../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../../lang'
import { accessoriesDetails, damageDetails, vehicleDetails, vehiclePhotos } from '../../constants'
import { TabContentStyle, CardBorderStyle, CardItemStyle } from '../../container/index.style'

function TabInsuredDetail({ draftQuotationsDetailsData }) {
  const formatValues = (value, label) => {
    if (label.includes('Foto Modifikasi')) {
      return <UploadFileV3 height="200px" disabled defaultValue={value} />
    }

    if (label.includes('Premi / ')) {
      return formatMoney(value, 0)
    }

    if (label.includes('Tipe Perlindungan Tahun')) {
      if (value === 'car-protection-comprehensive') {
        return 'Komprehensif'
      } else if (value === 'car-protection-tlo') {
        return 'TLO'
      }
      return value
    }

    if (label.includes('Harga Modifikasi')) {
      return formatMoney(value, 0)
    }

    switch (label) {
      case 'Nomor Plat':
        return value?.split(/[^0-9]/)[0]
      case 'Kode Belakang Plat':
        return value?.split(/[0-9]/)?.filter(Boolean)?.join('')
      case LANG_STRINGS.basicPremium:
      case LANG_STRINGS.adminFee:
      case LANG_STRINGS.stampDuty:
      case LANG_STRINGS.totalTransaction:
      case 'Harga Kendaraan':
        return formatMoney(value, 0)
      case LANG_STRINGS.startProtection:
        return moment(value).format('DD/MM/YYYY')
      case LANG_STRINGS.endProtection:
        return moment(value).format('DD/MM/YYYY')
      case 'Foto STNK':
      case 'Foto Cacat Bawaan':
      case 'Foto KTP':
        return <UploadFileV3 height="200px" disabled defaultValue={value} />
      default:
        return value
    }
  }

  const getNestedValue = (data, keys) => {
    if (!Array.isArray(keys)) return undefined // Prevent crash

    let value = data
    keys.forEach((key) => {
      value = value?.[key]
    })

    if (Array.isArray(value)) {
      return value.join(', ')
    }

    return value
  }

  const renderDetailCard = (title, data, list) => {
    return (
      <>
        {title && (
          <CustomText
            color={AgentColorPallette.black}
            weight={700}
            size="15px"
            bottom="12px"
            top="10px"
          >
            {title}
          </CustomText>
        )}
        <div className="bg-white data-container">
          {list?.map((item, index) => {
            // Check if the formatted value is an image
            const formattedValue = item.format
              ? formatValues(
                  item.value
                    ? item.value
                    : item.key
                      ? data?.[item.key]
                      : getNestedValue(data, item?.keys),
                  item.label
                )
              : item.value
                ? item.value
                : item.key
                  ? data?.[item.key]
                  : getNestedValue(data, item?.keys)

            // Determine if this is an image type by checking if formattedValue contains img or Image component
            const isImage =
              typeof formattedValue === 'object' ||
              (typeof formattedValue === 'string' && formattedValue.includes('<img'))

            return (
              <CardItemStyle border={index + 1 !== list.length} key={index}>
                <CardBorderStyle border={index + 1 !== list.length}>
                  {isImage ? (
                    // Vertical layout for images - label on top, image below
                    <div className="image-container">
                      <CustomText
                        color={AgentColorPallette.fontGrey}
                        size="12px"
                        weight={700}
                        bottom="8px"
                      >
                        {item.label}
                      </CustomText>
                      <div className="image-wrapper">{formattedValue}</div>
                    </div>
                  ) : (
                    // Standard horizontal layout for non-image content
                    <Row align="center" justify="space-between" gap={item.gap || null}>
                      <CustomText color={AgentColorPallette.fontGrey} size="12px" weight={700}>
                        {item.label}
                      </CustomText>
                      <CustomText
                        color={AgentColorPallette.regular}
                        size="13px"
                        weight={600}
                        textAlign={item.align || 'left'}
                      >
                        {formattedValue}
                      </CustomText>
                    </Row>
                  )}
                </CardBorderStyle>
              </CardItemStyle>
            )
          })}
        </div>
      </>
    )
  }

  const renderDetailCardPhoto = (title, data, list) => {
    return (
      <>
        {title && (
          <CustomText
            color={AgentColorPallette.black}
            weight={700}
            size="15px"
            bottom="12px"
            top="10px"
          >
            {title}
          </CustomText>
        )}
        <div className="bg-white data-container">
          {list?.map((item, index) => (
            <CardItemStyle border={index + 1 !== list.length} key={index}>
              <CardBorderStyle>
                <Row align="center" justify="space-between" gap={item.gap || null}>
                  <CustomText color={AgentColorPallette.fontGrey} size="12px" weight={700}>
                    {item.label}
                  </CustomText>
                </Row>
                <UploadFileV3
                  height="200px"
                  disabled
                  defaultValue={item.key ? data?.[item.key] : getNestedValue(data, item?.keys)}
                />
              </CardBorderStyle>
            </CardItemStyle>
          ))}
        </div>
      </>
    )
  }

  return (
    <TabContentStyle>
      {renderDetailCard(
        'Detail Kendaraan',
        draftQuotationsDetailsData?.policy_details,
        vehicleDetails
      )}
      {renderDetailCardPhoto(
        'Daftar Dokumen',
        draftQuotationsDetailsData?.policy_details,
        vehiclePhotos
      )}
      {draftQuotationsDetailsData?.policy_details?.accessories?.length !== 0 &&
        renderDetailCard(
          'Modifikasi Kendaraan',
          draftQuotationsDetailsData?.policy_details,
          accessoriesDetails(draftQuotationsDetailsData?.policy_details)
        )}
      {draftQuotationsDetailsData?.policy_details?.damage_photos &&
        renderDetailCard(
          'Cacat Bawaan',
          draftQuotationsDetailsData?.policy_details,
          damageDetails(draftQuotationsDetailsData?.policy_details)
        )}
    </TabContentStyle>
  )
}

export default TabInsuredDetail
