import moment from 'moment'
import {
  getExtraVehicleData,
  getPackagesReqBody,
} from '../../../../../../../helpers/getPackageBody'
import { checkValidateStartDate } from '../../../../../../../helpers/utility'

export const buildPkgDetailRequestBody = (draftQuotationsDetailsData, overrides = {}) => {
  const policyDetails = {
    ...draftQuotationsDetailsData?.policy_details,
  }

  // normalize invalid start date
  if (policyDetails.start_date && !checkValidateStartDate(policyDetails.start_date)) {
    policyDetails.start_date = moment().format('YYYY-MM-DD')
  }

  const body = {
    // base package payload
    ...getPackagesReqBody(policyDetails),

    // existing addons from policy
    ...(policyDetails.addons_data || {}),

    // extra vehicle fields
    ...getExtraVehicleData(policyDetails),

    // additional package params
    discount: policyDetails.discount,
    purchase_type: policyDetails.purchase_type,
    provider_branch: policyDetails.provider_branch,

    // runtime overrides
    ...overrides,
  }

  // optional fields
  if (policyDetails.category_name) {
    body.category_name = policyDetails.category_name
  }

  if (policyDetails.end_date) {
    body.end_date = policyDetails.end_date
  }

  if (policyDetails.year_based_package_type_map) {
    body.year_based_package_type_map = policyDetails.year_based_package_type_map
  }

  return body
}

export const buildUpdateDraftQuoteRequestBody = (
  draftQuotationsDetailsData,
  getPackageDetailData,
  overrides = {}
) => {
  return {
    section: 'mv_quote_summary',
    sub_section: 'mv_quote_summary',
    data: {
      ...draftQuotationsDetailsData.policy_details,
      package_data: getPackageDetailData,
      ...overrides,
    },
  }
}
