import { useHistory } from 'react-router'
import { ARROW_RIGHT_BLACK, MERCHANT_BLACK } from '../../../../../../../images'
import useEventTracker from '../../../../../../../hooks/trackers'
import { StyleContainer } from './index.styles'

function FooterChangePackage({ draftId, oldPolicyData, draftQuotationsDetailsData }) {
  const history = useHistory()
  const { trackUserEvent } = useEventTracker()

  const handleChangePackage = () => {
    trackUserEvent('[MV Renewal] Click Atur Ulang Penawaran', {
      renewal_allocation: oldPolicyData?.renewal_allocation,
      insurance_provider: draftQuotationsDetailsData?.policy_details?.provider?.name,
      vehicle_brand: draftQuotationsDetailsData?.policy_details?.brand_data?.name,
      vehicle_model: draftQuotationsDetailsData?.policy_details?.model_data?.model_name,
      vehicle_year: draftQuotationsDetailsData?.policy_details?.year,
      original_application_no: oldPolicyData?.application_no,
    })
    history.push(`/motor_vehicle/v2/${draftId}`)
  }

  return (
    <StyleContainer
      role="button"
      tabIndex={0}
      onClick={handleChangePackage}
      onKeyDown={(e) => e.key === 'Enter' && handleChangePackage()}
      data-testid="renewal-one-tap-footer-change-package"
    >
      <div className="left">
        <img className="icon" src={MERCHANT_BLACK} alt="" />
        <div>
          <div className="text-top">Penawaran tidak sesuai?</div>
          <div className="text-bottom">Atur ulang penawaran asuransi</div>
        </div>
      </div>
      <img className="icon" src={ARROW_RIGHT_BLACK} alt="" />
    </StyleContainer>
  )
}

export default FooterChangePackage
