import { useState, useEffect, useRef } from 'react'
import { Grid, Row } from '../../commonStyle/index.style'
import { ArrowWrapper, PolicyPaymentInfoStyle } from './index.style'
import CustomText from '../CustomText/index'
import { LANG_STRINGS } from '../../lang/index'
import { AgentColorPallette } from '../../configs/colorPallete'
import { formatMoney } from '../../helpers/utility'
import Button from '../Button/index'
import PaymentBottomSheet from './components/PaymentBottomSheet'
import { useUpdateGlobal } from '../../state/globalState/hooks/useGlobalContext'
import MVAddonReminderModal from '../../containers/Private/Packages/components/MVAddonReminderModal'

function MvPaymentInfo({
  policyDetails = {},
  isDiscountEditable = false,
  onDiscountChange = () => {},
  onShareClick = () => {},
  onBuyClick = () => {},
  isRedirected = false,
  onRedirectBackClick = () => {},
  showDiscountCtn = true,
  isShowAddonReminderModal,
  showAddonsModal = () => {},
  isShowConvertToPaylater,
  isConvertToPaylaterChecked,
  onConvertToPaylaterClick,
  isO2ORenewal = false,
  onO2ORenewalClick = () => {},
}) {
  const paymentBreakupRef = useRef(null)
  const [openPayment, setOpenPayment] = useState(false)
  const [openAddonReminder, setOpenAddonReminder] = useState(false)
  const [disableBtn, setDisableBtn] = useState(false)
  const [appliedDiscount, setAppliedDiscount] = useState(0)

  const [{ globalState: { isLoggedIn } = {} }] = useUpdateGlobal()

  useEffect(() => {
    if (policyDetails?.discount !== undefined) {
      setAppliedDiscount(policyDetails.discount)
    }
  }, [policyDetails?.discount])

  const handleDiscount = () => {
    // Get current discount value from PaymentBreakup component via ref
    const newDiscount = paymentBreakupRef.current?.getDiscountValue() ?? appliedDiscount
    setAppliedDiscount(newDiscount)
    onDiscountChange({ discount: newDiscount })
  }

  const handleBuy = () => {
    onBuyClick({ discount: appliedDiscount })
  }

  const getGridColumns = () => {
    if (isRedirected && !showDiscountCtn) return '1fr'
    if (isO2ORenewal) return '1fr'
    if (openPayment) return '1fr'
    return isLoggedIn ? '1fr 1fr 1fr' : '1fr 1fr'
  }

  return (
    <>
    <PolicyPaymentInfoStyle>
      {isShowConvertToPaylater && (
        <div className="convert-to-paylater" onClick={onConvertToPaylaterClick}>
          <input type="checkbox" checked={isConvertToPaylaterChecked} />
          <CustomText size="14px" weight="600" color={AgentColorPallette.darkCharcoal} bottom="0">
            {LANG_STRINGS.changeTransactionToPayLater}
          </CustomText>
        </div>
      )}
      <Grid gridColumn={getGridColumns()} gridGap="0.8rem" className="action-grid">
        {isRedirected && (
          <Button
            variant="filled"
            onClick={onRedirectBackClick}
            id="mobil-detail-agent-buy-pkg-click"
            disabled={disableBtn}
          >
            {LANG_STRINGS.backToInformation}
          </Button>
        )}
        {showDiscountCtn && !openPayment && !isO2ORenewal && (
          <div
            style={{ cursor: 'pointer' }}
            onClick={() => setOpenPayment((oldValue) => !oldValue)}
          >
            <CustomText color={AgentColorPallette.fontDarkerGrey} size="0.7em" weight={700}>
              {LANG_STRINGS.totalBill}
            </CustomText>
            <Row>
              <CustomText color={AgentColorPallette.ppBlue} size="0.75em" weight={800}>
                {formatMoney((policyDetails?.package_data?.total_bill || 0) - appliedDiscount, 0)}
              </CustomText>
              <CustomText size="12px" weight={700} color={AgentColorPallette.ppBlue} padLeft="10px">
                <ArrowWrapper>
                  <i className={`fas ${openPayment ? 'fa-angle-down' : 'fa-angle-up'}`} />
                </ArrowWrapper>
              </CustomText>
            </Row>
          </div>
        )}
        {openPayment && showDiscountCtn && (
          <Button
            variant="filled"
            id="mobil-detail-agent-buy-pkg-click"
            onClick={() => {
              handleDiscount()
              setOpenPayment(false)
            }}
            disabled={disableBtn}
          >
            {LANG_STRINGS.save}
          </Button>
        )}
        {isLoggedIn && !openPayment && !isO2ORenewal && !isRedirected && (
          <Button
            variant="outlined"
            onClick={onShareClick}
            id="mobil-detail-agent-buy-pkg-click"
            disabled={disableBtn}
          >
            {LANG_STRINGS.share}
          </Button>
        )}
        {!isRedirected && !openPayment && !isO2ORenewal && (
          <Button
            variant="filled"
            id="mobil-detail-agent-buy-pkg-click"
            onClick={() => {
              if (isShowAddonReminderModal?.()) {
                setOpenAddonReminder(true)
              } else {
                handleBuy()
                setOpenPayment(false)
              }
            }}
            disabled={disableBtn}
          >
            {LANG_STRINGS.buy}
          </Button>
        )}
        {!isRedirected && !openPayment && isO2ORenewal && (
          <Button variant="filled" onClick={onO2ORenewalClick} disabled={disableBtn}>
            Ajukan Renewal
          </Button>
        )}
      </Grid>
    </PolicyPaymentInfoStyle>
    {openAddonReminder && (
      <MVAddonReminderModal
        showModal={openAddonReminder}
        onClose={() => setOpenAddonReminder(false)}
        onClickYes={() => {
          showAddonsModal(true)
          setOpenAddonReminder(false)
        }}
        onClickNo={() => {
          handleBuy()
          setOpenPayment(false)
        }}
      />
    )}
    {openPayment && (
      <PaymentBottomSheet
        ref={paymentBreakupRef}
        show={openPayment}
        onClose={() => setOpenPayment(false)}
        policyDetails={policyDetails}
        isDiscountEditable={isDiscountEditable}
        appliedDiscount={appliedDiscount}
        setDisableBtn={setDisableBtn}
      />
    )}
    </>
  )
}

export default MvPaymentInfo
