import { useState, useCallback, useEffect } from 'react'
import { useParams } from 'react-router'
import { useHistory } from 'react-router-dom'
import {
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { Container } from '../../../../../../components'
import Tabs from '../../../../../../components/Tabs'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'
import {
  useGetDraftQuoteDetails,
  useGetRenewalOneTapDetails,
} from '../../../state/hooks/usePolicyState'
import HeaderCountdown from '../components/HeaderCountdown'
import PolicySummaryCard from '../components/PolicySummaryCard'
import FooterRenewalAllocation from '../components/FooterRenewalAllocation'
import FooterChangePackage from '../components/FooterChangePackage'
import FooterPremiumBreakdown from '../components/FooterPremiumBreakdown'
import TabComparison from '../components/TabComparison'
import TabInsuranceDetail from '../../MVPolicyConfirmationPage/components/TabInsuranceDetail'
import TabInsuredDetail from '../../MVPolicyConfirmationPage/components/TabInsuredDetail'
import TabPolicyDetail from '../../MVPolicyConfirmationPage/components/TabPolicyDetail'
import { TABS_DATA, TABS_KEYS } from './constants'
import { StyleContainer } from './index.styles'

function RenewalOneTapContainer() {
  const history = useHistory()
  const { policyId } = useParams()

  const [activeTab, setActiveTab] = useState(TABS_DATA[0])

  const [{ getRenewalOneTapDetailsData }, _getRenewalOneTapDetailsRequest] =
    useGetRenewalOneTapDetails()
  const [{ draftQuotationsDetailsData }, _draftQuotationsDetailsRequest] = useGetDraftQuoteDetails()
  const [
    {
      GET_RENEWAL_ONE_TAP_DETAILS_LOADER,
      DRAFT_QUOTATIONS_DETAILS_LOADER,
      CREATE_OFFLINE_QUOTE_LOADER,
    },
  ] = useLoaderContextValue()
  const [{ getRenewalOneTapDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const {
    draft_id: draftId,
    comparison: comparisonData,
    old_policy_detail: oldPolicyData,
    request_quote_detail: o2oRequestData,
  } = getRenewalOneTapDetailsData?.data || {}

  const getRenewalOneTapDetailsRequest = useCallback(() => {
    if (!policyId) return
    _getRenewalOneTapDetailsRequest({ policyId })
  }, [_getRenewalOneTapDetailsRequest, policyId])

  const draftQuotationsDetailsRequest = useCallback(() => {
    if (!draftId) return
    _draftQuotationsDetailsRequest({ draftQuoteId: draftId })
  }, [_draftQuotationsDetailsRequest, draftId])

  useEffect(() => {
    getRenewalOneTapDetailsRequest()
  }, [getRenewalOneTapDetailsRequest])

  useEffect(() => {
    if (draftId) {
      draftQuotationsDetailsRequest()
    }
  }, [draftQuotationsDetailsRequest, draftId])

  useEffect(() => {
    if (!getRenewalOneTapDetailsStatus || getRenewalOneTapDetailsStatus === 'success') return
    ShowSnackbar.error({ text: ERROR_LANG.generalErrorTryAgain })
    resetError(['getRenewalOneTapDetailsStatus'])
  }, [getRenewalOneTapDetailsStatus, resetError])

  const pageLoader =
    (GET_RENEWAL_ONE_TAP_DETAILS_LOADER && !getRenewalOneTapDetailsData) ||
    (DRAFT_QUOTATIONS_DETAILS_LOADER && !draftQuotationsDetailsData) ||
    CREATE_OFFLINE_QUOTE_LOADER

  return (
    <Container
      title={LANG_STRINGS.policyExtension}
      loader={pageLoader}
      hideBottomTabs
      displayBackButton
      onBackClick={() => history.goBack()}
    >
      <StyleContainer>
        <div className="one-tap-header">
          <HeaderCountdown oldPolicyData={oldPolicyData} />
        </div>

        <PolicySummaryCard oldPolicyData={oldPolicyData} comparisonData={comparisonData} />
        <Tabs
          data={TABS_DATA}
          defaultTab={activeTab}
          onClick={(tab) => setActiveTab(tab)}
          isSticky
          top="88px"
        />
        <div className="tab-content">
          {activeTab.value === TABS_KEYS.COMPARISON && (
            <TabComparison oldPolicyData={oldPolicyData} comparisonData={comparisonData} />
          )}
          {activeTab.value === TABS_KEYS.INSURANCE_DETAIL && (
            <TabInsuranceDetail
              id={getRenewalOneTapDetailsData?.draft_id}
              draftQuotationsDetailsData={draftQuotationsDetailsData}
            />
          )}
          {activeTab.value === TABS_KEYS.INSURED_DETAIL && (
            <TabInsuredDetail draftQuotationsDetailsData={draftQuotationsDetailsData} />
          )}
          {activeTab.value === TABS_KEYS.POLICY_DETAIL && (
            <TabPolicyDetail draftQuotationsDetailsData={draftQuotationsDetailsData} />
          )}
        </div>

        <div className="one-tap-footer">
          <FooterRenewalAllocation oldPolicyData={oldPolicyData} />
          <FooterChangePackage
            draftId={draftId}
            oldPolicyData={oldPolicyData}
            draftQuotationsDetailsData={draftQuotationsDetailsData}
          />
          <FooterPremiumBreakdown
            draftId={draftId}
            oldPolicyData={oldPolicyData}
            o2oRequestData={o2oRequestData}
            draftQuotationsDetailsData={draftQuotationsDetailsData}
            getRenewalOneTapDetailsRequest={getRenewalOneTapDetailsRequest}
            draftQuotationsDetailsRequest={draftQuotationsDetailsRequest}
          />
        </div>
      </StyleContainer>
    </Container>
  )
}

export default RenewalOneTapContainer
