import BottomActionSheet from '../../../../../components/BottomActionSheet'
import {
  Box,
  Box1,
  ButtonPadding,
  DesText,
  Image,
  Image1,
  ShareQuotationDiv,
  ShareQuotationStyle,
  Text,
  Text1,
  Top,
} from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import { Button, CustomText } from '../../../../../components'
import { useCallback, useEffect, useRef, useState } from 'react'
import CircularLoader from '../../../../../components/CircularLoader'
import { getFromLocalStorageData } from '../../../../../helpers/localstorage'
import { useHistory, useParams } from 'react-router'
import {
  CLOSE_BLACK_ICON,
  DOWNLOAD_ICON_V2,
  HOME_ICON,
  LINK_ICON,
  MV_INFO,
  MV_QS_ICON,
  MV_SEND_ICON,
  SENT_ICON,
  UMBRELLA_ICON,
} from '../../../../../images'
import { copySharingData } from '../../../../../helpers/utility'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { APP_HOST } from '../../../../../configs/url'
import { regex } from '../../../../../constants/regex'
import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import DynamicFormV3 from '../../../../../components/DynamicFormV3'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import {
  useGetDownloadDraftPdf,
  useGetDraftQuoteDetails,
  useShareDraftQuoteToCustomer,
  useUpdateDraftQuote,
} from '../../state/hooks/usePolicyState'
import { downloadFile } from '../../../../../helpers/mitraUtils/mitra-utility'

export const getShareQuotationWithCustomerTravel = () => ({
  fieldData: [
    {
      label: 'Nama Lengkap Pelanggan',
      type: 'input',
      name: 'name',
      required: true,
    },
    {
      label: 'Nomor Ponsel Pelanggan',
      type: 'input',
      name: 'mobile_no',
      required: true,
      validator: (value = '') => {
        if (!['+62', '62', '08'].some((pre) => value.startsWith(pre)))
          return ERROR_LANG.phoneNumberNotStartsWith62
        if (value.startsWith('+62') && value.length > 15) return ERROR_LANG.max15DigitAllowed
        if (value.length > 14) return ERROR_LANG.max14DigitAllowed
        if (!regex.phoneRegex.test(value)) return ERROR_LANG.phoneNumberError
      },
    },
    {
      label: 'Email Pelanggan',
      type: 'input',
      name: 'email',
      required: true,
      validator: (value = '') => {
        if (!regex.emailRegex.test(value)) {
          return ERROR_LANG.emailRequiredError
        }
        return ''
      },
    },
  ],
})

function ShareQuotation({ show, onClose, loader, draftId }) {
  const formRef = useRef()
  const history = useHistory()
  const [userBlurred, setUserBlurred] = useState(true)
  const [formValues, setFormValues] = useState({ name: '', email: '', mobile_no: '' })
  const [showShareDetailPopup, setShowShareDetailPopup] = useState(false)
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const [, shareDraftQuoteReq] = useShareDraftQuoteToCustomer()
  const [{ shareDraftQuoteStatus }] = useErrorContextValue()
  const [{ getDownloadDraftPdfData = {} }, getDownloadDraftPdfReq] = useGetDownloadDraftPdf()
  const [{ getDownloadDraftPdfStatus }, dispatchError] = useErrorContextValue()

  const renderIconText = useCallback((icon, text) => {
    return (
      <Top paddingTop="20px">
        <Image src={icon} alt={text} />
        <Text bold={700} size="10px">
          {text}
        </Text>
      </Top>
    )
  }, [])

  const renderSentIcon = useCallback((icon, text) => {
    return (
      <Top>
        <Image1 src={icon} alt={text} />
      </Top>
    )
  }, [])

  useEffect(() => {
    if (shareDraftQuoteStatus !== 'success' && shareDraftQuoteStatus !== undefined) {
      ShowSnackbar.error({ text: ERROR_LANG.errorWhileUpdating })
    } else if (shareDraftQuoteStatus === 'success') {
      setShowShareDetailPopup(true)
    }
    resetError(['shareDraftQuoteStatus'])
  }, [shareDraftQuoteStatus])

  useEffect(() => {
    if (draftId) {
      getDraftQuoteDetailsReq({ draftQuoteId: draftId })
    }
  }, [getDraftQuoteDetailsReq, draftId])

  useEffect(() => {
    if (draftQuotationsDetailsData?.customer_detail?.name) {
      setFormValues({
        name: draftQuotationsDetailsData?.customer_detail.name,
        mobile_no: draftQuotationsDetailsData?.customer_detail.mobile_no,
        email: draftQuotationsDetailsData?.customer_detail.email,
      })
    }
  }, [draftQuotationsDetailsData])

  useEffect(() => {
    if (getDownloadDraftPdfStatus === 'success' && getDownloadDraftPdfData) {
      downloadFile(getDownloadDraftPdfData.pdf_url)
      dispatchError(
        resetError({
          getDownloadDraftPdfStatus: '',
        })
      )
    }
  }, [getDownloadDraftPdfStatus, getDownloadDraftPdfData, dispatchError])

  const body = {
    customer_data: {
      email: formValues.email,
      mobile_no: formValues.mobile_no,
      name: formValues.name,
      ...draftQuotationsDetailsData?.customer_detail,
    },
    draft_id: draftId,
  }

  const handleCustomerForm = (name, value) => {
    setFormValues({
      ...formValues,
      [name]: value,
    })
  }

  const handleSendQuote = () => {
    if (formValues) {
      shareDraftQuoteReq({
        body,
      })
    }
  }

  const getSharingData = (source) => {
    const linkOfShare = `${APP_HOST}/motor_vehicle/draft/policy/${draftId}/?source=${source}`
    return {
      link: linkOfShare,
    }
  }

  const handleCopyLink = () => {
    const sharingDate = getSharingData('quotation_copy')
    copySharingData(sharingDate.link)
    ShowSnackbar.success({
      visible: true,
      text: 'Menyalin ke clipboard berhasil',
    })
  }

  const handleDownloadPdf = () => {
    if (draftId) {
      getDownloadDraftPdfReq({ draftId: draftId })
    }
  }

  const handleBackHome = () => {
    history.push({
      pathname: '/dashboard',
    })
  }

  return (
    <BottomActionSheet show={show} onCloseSheet={onClose} zIndex={4}>
      {!showShareDetailPopup && (
        <>
          <ShareQuotationStyle>
            <CircularLoader isLoading={loader}>
              <div className="close-cross">
                <img src={CLOSE_BLACK_ICON} alt="" className="img-width" onClick={onClose} />
              </div>
              <div className="icon-container">
                <div className="info-icon">
                  <img src={MV_QS_ICON} alt="info-icon" />
                </div>
              </div>
              <div className="confirmation-header">Bagikan Penawaran</div>
              <div className="confirmation-text">
                Lengkapi data dibawah untuk mengirimkan penawaran asuransi.
              </div>
              <div className="padding">
                <DynamicFormV3
                  formData={getShareQuotationWithCustomerTravel()}
                  onChange={handleCustomerForm}
                  ref={formRef}
                  values={formValues}
                  setUserBlurred={setUserBlurred}
                />
              </div>
            </CircularLoader>
          </ShareQuotationStyle>
          <ButtonPadding>
            <Button variant="filled" onClick={handleSendQuote}>
              {LANG_STRINGS.share}
            </Button>
          </ButtonPadding>
        </>
      )}
      {showShareDetailPopup && (
        <>
          <ShareQuotationDiv>
            <Box1>
              <div className="box-adjust box-content">{renderSentIcon(MV_SEND_ICON)}</div>
            </Box1>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              weight={800}
              size="15px"
              textAlign="center"
            >
              {'Penawaran Terkirim'}
            </CustomText>
            <DesText>
              {'Detail penawaran telah berhasil terkirim ke WhatsApp dan Email yang dituju.'}
            </DesText>
            <Text bold={800} size="12px" lineHeight="12px">
              {LANG_STRINGS.otherOptions}
            </Text>
            <Box>
              <div onClick={handleDownloadPdf} className="box-adjust box-content">
                {renderIconText(DOWNLOAD_ICON_V2, 'Download Penawaran')}
              </div>
              <div onClick={handleCopyLink} className="box-adjust box-content">
                {renderIconText(LINK_ICON, 'Salin Tautan Penawaran')}
              </div>
              <div onClick={handleBackHome} className="box-adjust box-content">
                {renderIconText(HOME_ICON, 'Kembali Ke Beranda')}
              </div>
            </Box>
          </ShareQuotationDiv>
          <ButtonPadding>
            <Button variant="filled" onClick={onClose}>
              TUTUP
            </Button>
          </ButtonPadding>
        </>
      )}
    </BottomActionSheet>
  )
}

export default ShareQuotation
