import { useHistory } from 'react-router'
import { useMemo, useState, useCallback, useEffect } from 'react'
import {
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import MvPaymentInfo from '../../../../../../../components/MvPaymentInfo'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import useEventTracker from '../../../../../../../hooks/trackers'
import {
  useCompleteDraftQuote,
  useCreateOfflineQuote,
  useUpdateDraftQuote,
} from '../../../../state/hooks/usePolicyState'
import { useGetPkgDetail } from '../../../../../Packages/state/hooks/usePackages'
import ShareQuotation from '../../../MVPolicyQuotationPopup'
import PopupDisclaimer from '../../../MVPolicyConfirmationPage/components/PopupDisclaimer'
import { RENEWAL_ALLOCATION } from '../../container/constants'
import {
  buildPkgDetailRequestBody,
  buildUpdateDraftQuoteRequestBody,
} from './helpers'
import { StyleContainer } from './index.styles'

function FooterPremiumBreakdown(props) {
  const {
    draftId,
    oldPolicyData,
    o2oRequestData,
    draftQuotationsDetailsData,
    getRenewalOneTapDetailsRequest,
    draftQuotationsDetailsRequest,
  } = props

  const history = useHistory()
  const [showShareSheet, setShowShareSheet] = useState(false)
  const [showPopupDisclaimer, setShowPopupDisclaimer] = useState(false)
  const [discount, setDiscount] = useState(
    draftQuotationsDetailsData?.policy_details?.discount || 0
  )

  const [{ getPackageDetailData = {} }, getPkgDetailsReq] = useGetPkgDetail()
  const [, updateDraftQuotationReq] = useUpdateDraftQuote()
  const [{ completeDraftQuoteData = {} }, updateCompleteDraftQuoteReq] = useCompleteDraftQuote()
  const [{ createOfflineQuoteData }, createOfflineQuoteRequest] = useCreateOfflineQuote()
  const [{ COMPLETE_DRAFT_QUOTE_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ getPackageDetailStatus, updateDraftQuotationStatus, createOfflineQuoteStatus }] =
    useErrorContextValue()
  const { resetError } = useResetError()
  const { trackUserEvent } = useEventTracker()

  const handleDiscountChange = useCallback(
    ({ discount }) => {
      getPkgDetailsReq({
        body: buildPkgDetailRequestBody(draftQuotationsDetailsData, { discount: discount }),
        packageCode: draftQuotationsDetailsData?.provider_package_code,
      })
      setDiscount(discount)
    },
    [getPkgDetailsReq, draftQuotationsDetailsData]
  )

  useEffect(() => {
    if (getPackageDetailStatus === 'success') {
      updateDraftQuotationReq({
        body: buildUpdateDraftQuoteRequestBody(draftQuotationsDetailsData, getPackageDetailData, {
          discount: discount,
        }),
        draftQuoteId: draftId,
      })
      resetError(['getPackageDetailStatus'])
    }
  }, [
    resetError,
    draftId,
    discount,
    updateDraftQuotationReq,
    draftQuotationsDetailsData,
    getPackageDetailData,
    getPackageDetailStatus,
  ])

  useEffect(() => {
    if (updateDraftQuotationStatus === 'success') {
      getRenewalOneTapDetailsRequest()
      draftQuotationsDetailsRequest()
      resetError(['updateDraftQuotationStatus'])
    }
  }, [
    resetError,
    draftId,
    updateDraftQuotationStatus,
    getRenewalOneTapDetailsRequest,
    draftQuotationsDetailsRequest,
  ])

  const handleCompleteDraft = () => {
    if (COMPLETE_DRAFT_QUOTE_LOADER === undefined) {
      trackUserEvent('[MV Renewal] Confirm Renew Policy', {
        renewal_allocation: oldPolicyData?.renewal_allocation,
        insurance_provider: draftQuotationsDetailsData?.policy_details?.provider?.name,
        vehicle_brand: draftQuotationsDetailsData?.policy_details?.brand_data?.name,
        vehicle_model: draftQuotationsDetailsData?.policy_details?.model_data?.model_name,
        vehicle_year: draftQuotationsDetailsData?.policy_details?.year,
        original_application_no: oldPolicyData?.application_no,
      })
      updateCompleteDraftQuoteReq({
        draftQuoteId: draftId,
      })
    }
  }

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          COMPLETE_DRAFT_QUOTE_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (completeDraftQuoteData.id) {
      history.push(`/payment/car-protection/${completeDraftQuoteData.id}`)
    }
  }, [history, completeDraftQuoteData])

  const isO2ORenewal = useMemo(
    () => oldPolicyData?.renewal_allocation === RENEWAL_ALLOCATION.UW_REVIEW,
    [oldPolicyData]
  )

  const handleO2ORenewal = () => {
    trackUserEvent('[MV Renewal] Confirm Renew Policy', {
      renewal_allocation: oldPolicyData?.renewal_allocation,
      insurance_provider: o2oRequestData?.prov_maps?.[0]?.name,
      vehicle_brand: o2oRequestData?.brand_data?.name,
      vehicle_model: o2oRequestData?.model_data?.model_name,
      vehicle_year: o2oRequestData?.year,
      original_application_no: oldPolicyData?.application_no,
    })
    createOfflineQuoteRequest({
      body: o2oRequestData,
    })
  }

  useEffect(() => {
    if (createOfflineQuoteStatus === 'success') {
      history.push(`/offline/success/${createOfflineQuoteData.id}`)
      resetError(['createOfflineQuoteStatus'])
    } else if (createOfflineQuoteStatus) {
      ShowSnackbar.error({ text: createOfflineQuoteStatus })
      resetError(['createOfflineQuoteStatus'])
    }
  }, [history, resetError, createOfflineQuoteStatus, createOfflineQuoteData])

  return (
    <StyleContainer data-testid="renewal-one-tap-footer-premium-breakdown">
      <MvPaymentInfo
        policyDetails={draftQuotationsDetailsData?.policy_details}
        isDiscountEditable={true}
        onDiscountChange={handleDiscountChange}
        onShareClick={() => setShowShareSheet(true)}
        onBuyClick={() => setShowPopupDisclaimer(true)}
        isO2ORenewal={isO2ORenewal}
        onO2ORenewalClick={handleO2ORenewal}
      />
      {showPopupDisclaimer && (
        <PopupDisclaimer
          show={showPopupDisclaimer}
          onConfirmClick={handleCompleteDraft}
          onClose={() => setShowPopupDisclaimer(false)}
        />
      )}
      {showShareSheet && (
        <ShareQuotation
          draftId={draftId}
          show={showShareSheet}
          onClose={() => setShowShareSheet(false)}
        />
      )}
    </StyleContainer>
  )
}

export default FooterPremiumBreakdown
