import _ from 'lodash'
import { formatDate } from '../../../../../../../helpers/formatDate'
import { formatMoney, formatNumber } from '../../../../../../../helpers/utility'
import { GREEN_CHECK_LINE, RED_CROSS_LINE } from '../../../../../../../images'

const formatBoolean = (value) => {
  if (value === true) {
    return <img className="status-icon" src={GREEN_CHECK_LINE} alt="included" />
  }
  return <img className="status-icon" src={RED_CROSS_LINE} alt="included" />
}

const mapAddonsData = (comparisonData) => {
  const map = new Map()

  // 1. Insert based on old_policy order
  comparisonData?.addons?.old_policy?.items?.forEach(({ id, label, included }) => {
    map.set(id, {
      id,
      label,
      oldValue: included,
      newValue: false,
    })
  })

  // 2. Update existing OR append new ones from new_policy
  comparisonData?.addons?.new_policy?.items?.forEach(({ id, label, included }) => {
    if (map.has(id)) {
      map.get(id).newValue = included
    } else {
      // appended at bottom
      map.set(id, {
        id,
        label,
        oldValue: false,
        newValue: included,
      })
    }
  })

  return [...map.values()]
}

