import { useMemo } from 'react'
import { GREEN_CHECK_LINE, INFO_CIRCLE_BLACK, HOURGLASS_GOLD } from '../../../../../../../images'
import { RENEWAL_ALLOCATION } from '../../container/constants'
import { StyleContainer } from './index.styles'

function FooterRenewalAllocation({ oldPolicyData }) {
  const data = useMemo(() => {
    switch (oldPolicyData?.renewal_allocation) {
      case RENEWAL_ALLOCATION.AUTO_RENEW:
        return {
          iconInfo: INFO_CIRCLE_BLACK,
          iconStatus: GREEN_CHECK_LINE,
          text: (
            <div className="text auto-renewal">
              Renewal dapat dilakukan langsung dengan jenis proteksi yang{' '}
              <strong>sama dengan polis sebelumnya</strong>.
            </div>
          ),
        }
      case RENEWAL_ALLOCATION.TLO_ONLY:
        return {
          iconInfo: INFO_CIRCLE_BLACK,
          iconStatus: GREEN_CHECK_LINE,
          text: (
            <div className="text tlo-only">
              Renewal dapat dilakukan langsung dengan jenis proteksi{' '}
              <strong>TLO (Total Loss Only)</strong>.
            </div>
          ),
        }
      case RENEWAL_ALLOCATION.UW_REVIEW:
        return {
          iconInfo: INFO_CIRCLE_BLACK,
          iconStatus: HOURGLASS_GOLD,
          text: (
            <div className="text manual-review">
              Renewal membutuhkan <strong>review manual</strong> oleh Asuransi. Pengajuan akan masuk
              ke dalam <strong>pesanan manual</strong>.
            </div>
          ),
        }
      default:
        return {}
    }
  }, [oldPolicyData])

  return (
    <StyleContainer data-testid="renewal-one-tap-footer-allocation">
      <div className="left">
        {data?.iconInfo && <img className="icon" src={data?.iconInfo} alt="" />}
        {data?.text}
      </div>
      {data?.iconStatus && <img className="icon" src={data?.iconStatus} alt="" />}
    </StyleContainer>
  )
}

export default FooterRenewalAllocation
