import { getDateDifference, isDateBefore } from '../../../../../../../helpers/formatDate'

export const RENEWAL_EXPIRY = {
  URGENT: 'urgent',
  WARNING: 'warning',
  EXPIRED: 'expired',
}

export const getRenewalExpiryColor = (expiryDate) => {
  if (!expiryDate) return null

  const isExpired = isDateBefore(expiryDate, new Date(), true)
  if (isExpired) {
    return RENEWAL_EXPIRY.EXPIRED
  }

  const diff = getDateDifference(expiryDate)
  const isAtLeast15Days = diff?.years > 0 || diff?.months > 0 || diff?.days >= 15
  if (isAtLeast15Days) {
    return RENEWAL_EXPIRY.WARNING
  }
  return RENEWAL_EXPIRY.URGENT
}
