import ComparisonTable from './ComparisonTable'
import { COMPARISON_SECTIONS } from './constants'
import { StyleContainer } from './index.styles'

function TabComparison({ comparisonData, oldPolicyData }) {
  return (
    <StyleContainer data-testid="renewal-one-tap-tab-comparison">
      {COMPARISON_SECTIONS({ comparisonData }).map((section) => (
        <ComparisonTable key={section.id} section={section} oldPolicyData={oldPolicyData} />
      ))}
    </StyleContainer>
  )
}

export default TabComparison
