import _ from 'lodash'
import { HOURGLASS_GOLD } from '../../../../../../../images'
import { RENEWAL_ALLOCATION } from '../../container/constants'
import { ComparisonCardStyle, ComparisonTableStyle } from './index.styles'

function ComparisonTable({ section, oldPolicyData }) {
  const isUwReview = oldPolicyData?.renewal_allocation === RENEWAL_ALLOCATION.UW_REVIEW
  return (
    <ComparisonCardStyle data-testid={`comparison-section-${section.id}`}>
      <div className="section-title">{section.title}</div>

      <ComparisonTableStyle>
        <div className="table-row table-header">
          <div className="col col-label">{section.labelHeader}</div>
          <div className="col col-old">Polis Lama</div>
          <div className="col col-new">Polis Baru</div>
        </div>
        {section.rows?.length === 0 && (
          <div className="table-row table-body">
            <div className="col col-centered">
              <span>{section.emptyPlaceholder}</span>
            </div>
          </div>
        )}
        {section.rows.map((row, index) => (
          <div key={index} className={`table-row table-body ${index % 2 === 1 ? 'striped' : ''}`}>
            <div className="col col-label">
              <span>{row.label}</span>
            </div>
            <div className="col col-old">
              <span>{row.format?.(row.oldValue)}</span>
            </div>
            <div className="col col-new">
              {isUwReview && _.isNil(row.newValue) ? (
                <img src={HOURGLASS_GOLD} alt="need review" />
              ) : (
                <span>{row.format?.(row.newValue)}</span>
              )}
            </div>
          </div>
        ))}
      </ComparisonTableStyle>
    </ComparisonCardStyle>
  )
}

export default ComparisonTable
