export const protectionDetails = (data) => {
  
  const staticFields = [
    {
      label: LANG_STRINGS.startProtection,
      keys: ['start_date'],
      format: true
    },
    {
      label: LANG_STRINGS.endProtection,
      keys: ['end_date'],
      format: true
    },
    {
      label: 'Periode Perlindungan',
      value: `${data?.year_based_package_type_map?.length || 0} Tahun`
    }
  ];

  const dynamicYearFields = (data?.year_based_package_type_map || []).map((item) => ({
    label: `Tipe Perlindungan Tahun #${item.year}`,
    value: item.package_type,
    format: true
  }));

  return [...staticFields, ...dynamicYearFields];
};

export const accessoriesDetails = (data) => {

  const dynamicYearFields = (data?.accessories || []).flatMap((item, index) => [
  {
    label: `Foto Modifikasi #${index + 1}`,
    value: item.img,
    format: true
  },
  {
    label: `Nama Modifikasi #${index + 1}`,
    value: item.name,
  },
  {
    label: `Harga Modifikasi #${index + 1}`,
    value: item.sum_insured,
    format: true
  },
]);
  return [...dynamicYearFields];
};

export const damageDetails = (data) => {

   const dynamicYearFields = Object.values(data?.damage_photos || {}).map((item, index) => ({
    label: `Foto Cacat Bawaan`,
    value: item.original,
    format: true
  }));

  const staticFields = [
    {
      label: 'Keterangan Cacat Bawaan #1',
      keys: ['damage_remarks'],
    },
  ];

 

  return [...dynamicYearFields, ...staticFields];
};

